export function actionMenu(doc,label='More'){
 const details=doc.createElement('details'),summary=doc.createElement('summary'),body=doc.createElement('div');details.className='admin-action-menu';summary.textContent=label;body.className='admin-action-options';details.append(summary,body);details.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();details.open=false;summary.focus();}});body.addEventListener('click',e=>{if(e.target.closest('button'))details.open=false;});return {element:details,body};
}
export function confirmPermanentDelete(doc,label){
 const active=doc.activeElement,invoker=active?.closest('.admin-action-menu')?.querySelector('summary')||active,dialog=doc.createElement('dialog'),title=doc.createElement('h2'),message=doc.createElement('p'),actions=doc.createElement('div'),cancel=doc.createElement('button'),remove=doc.createElement('button');title.id='admin-delete-title';title.textContent='Delete permanently?';dialog.setAttribute('aria-labelledby',title.id);message.textContent='“'+label+'” will be permanently removed. This cannot be undone.';cancel.type=remove.type='button';cancel.textContent='Cancel';remove.textContent='Delete permanently';remove.className='destructive';actions.className='dialog-actions';actions.append(cancel,remove);dialog.append(title,message,actions);doc.body.append(dialog);
 return new Promise(resolve=>{let done=false;const finish=value=>{if(done)return;done=true;dialog.close();dialog.remove();if(invoker?.isConnected)invoker.focus();resolve(value);};cancel.addEventListener('click',()=>finish(false));remove.addEventListener('click',()=>finish(true));dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false);});dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finish(false);}if(e.key==='Tab'&&(e.shiftKey&&doc.activeElement===cancel||!e.shiftKey&&doc.activeElement===remove)){e.preventDefault();(e.shiftKey?remove:cancel).focus();}});dialog.showModal();cancel.focus();});
}
